sp_widget.client_script:
function() {

    var c = this;

    c.searchText = "";
    c.filterStatus = "";
    c.filterCaregiver = "";

    c.patientFilter = function(patient){

        var searchMatch =
        !c.searchText ||

        patient.name.toLowerCase().indexOf(c.searchText.toLowerCase()) > -1 ||

        patient.medication.toLowerCase().indexOf(c.searchText.toLowerCase()) > -1 ||

        patient.caregiver.toLowerCase().indexOf(c.searchText.toLowerCase()) > -1;

        var statusMatch =
        !c.filterStatus ||
        patient.status == c.filterStatus;

        var caregiverMatch =
        !c.filterCaregiver ||
        patient.caregiver == c.filterCaregiver;

        return searchMatch &&
               statusMatch &&
               caregiverMatch;
    };

    c.viewPatient = function(patient){

        alert(
            patient.name +
            "\nMedication: " +
            patient.medication
        );

    };

}

sp_widget.css:
.patient-list-widget{
    background:#fff;
    border-radius:16px;
    padding:24px;
    box-shadow:0 2px 12px rgba(0,0,0,.08);
}

.widget-header{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:20px;
}

.widget-header h3{
    margin:0;
    font-size:18px;
    font-weight:700;
    color:#1a2332;
}

.header-right{
    display:flex;
    gap:12px;
    align-items:center;
}

.search-box-wrapper{
    position:relative;
}

.search-box-wrapper i{
    position:absolute;
    left:12px;
    top:50%;
    transform:translateY(-50%);
    color:#94a3b8;
}

.search-box-wrapper input{
    width:280px;
    padding:10px 12px 10px 38px;
    border:1px solid #dbe2ea;
    border-radius:8px;
}

.search-box-wrapper input:focus{
    outline:none;
    border-color:#1a73e8;
}

.header-right select{
    padding:10px 12px;
    border:1px solid #dbe2ea;
    border-radius:8px;
    min-width:150px;
    background:#fff;
}

.patient-table{
    width:100%;
    border-collapse:collapse;
}

.patient-table th{
    background:#f8fafc;
    color:#64748b;
    font-size:12px;
    text-transform:uppercase;
    padding:12px;
    text-align:left;
}

.patient-table td{
    padding:14px 12px;
    border-bottom:1px solid #eef2f7;
    font-size:14px;
}

.patient-table tr:hover{
    background:#f8fafc;
}

.patient-name{
    display:flex;
    align-items:center;
    gap:10px;
}

.avatar{
    width:35px;
    height:35px;
    border-radius:50%;
    background:#1a73e8;
    color:#fff;
    display:flex;
    align-items:center;
    justify-content:center;
    font-size:12px;
    font-weight:700;
}

.blood-badge{
    background:#fee2e2;
    color:#dc2626;
    padding:4px 10px;
    border-radius:12px;
    font-size:12px;
    font-weight:600;
}

.status-badge{
    padding:4px 10px;
    border-radius:12px;
    font-size:12px;
    font-weight:600;
}

.status-active{
    background:#dcfce7;
    color:#16a34a;
}

.status-inactive{
    background:#f1f5f9;
    color:#64748b;
}

.status-critical{
    background:#fee2e2;
    color:#dc2626;
}

.action-btn{
    background:#1a73e8;
    color:#fff;
    border:none;
    padding:7px 14px;
    border-radius:6px;
    cursor:pointer;
}

.action-btn:hover{
    background:#1558b0;
}

